select * from (select Part_Oem, PartNo, PartName, PartModels, Partprodu, Partunit, 0 Wareamount, PartSaleprc, (select top 1 base_str from sys_base where base_name='仓库' and shopId=1) WareName, '' PosiName, '' PartNote, PartType, 0 PartVouPrc, 0 performWork, 0 performWorkPer, 0 performSale,0 performSalePer,0 PartBSaleprc, Partpurpric,0 PartInPrice, shopId, id from par_PartBase where shopId={shopId} and partNo not in (select partNo from par_PartWare where shopid={shopId}) union select Part_Oem, PartNo, PartName, PartModels, Partprodu, Partunit, Wareamount, PartSaleprc, WareName, PosiName, PartNote, PartType, PartVouPrc, performWork, performWorkPer, performSale, performSalePer, PartBSaleprc, Partpurpric, PartInPrice, shopId, id from par_PartWare where shopid='{shopId}') a where {strSqlPage}PartNo like '%{PartNo}%' and PartName like '%{PartName}%' and PartModels like '%{PartModels}%' and Partprodu like '%{Partprodu}%' and WareName like '%{WareName}%' and PosiName like '%{PosiName}%' and wareAmount <> case '{notZero}' when '1' then 0 else -100000 end order by Wareamount desc
